import React from 'react';

const initial={code:'',companyName:'',contactName:'',phone:'',whatsapp:'',email:'',address:'',category:'',capabilities:'',paymentTerms:'',bankDetails:'',active:true};
export default function VendorForm({onSubmit,submitting}){const [form,setForm]=React.useState(initial);const set=(k,v)=>setForm(f=>({...f,[k]:v}));const submit=e=>{e.preventDefault();onSubmit(form)};return <form className="entity-form" onSubmit={submit}><div className="form-grid two"><label>Vendor code<input value={form.code} onChange={e=>set('code',e.target.value)} required/></label><label>Company name<input value={form.companyName} onChange={e=>set('companyName',e.target.value)} required/></label><label>Contact name<input value={form.contactName} onChange={e=>set('contactName',e.target.value)}/></label><label>Category<input value={form.category} onChange={e=>set('category',e.target.value)} placeholder="Fabrication / Printing / Electrical"/></label><label>Phone<input value={form.phone} onChange={e=>set('phone',e.target.value)}/></label><label>WhatsApp<input value={form.whatsapp} onChange={e=>set('whatsapp',e.target.value)}/></label><label>Email<input type="email" value={form.email} onChange={e=>set('email',e.target.value)}/></label><label>Payment terms<input value={form.paymentTerms} onChange={e=>set('paymentTerms',e.target.value)} placeholder="30 days"/></label></div><label>Address<textarea rows="2" value={form.address} onChange={e=>set('address',e.target.value)}/></label><label>Capabilities<textarea rows="3" value={form.capabilities} onChange={e=>set('capabilities',e.target.value)} placeholder="Laser cutting, powder coating, acrylic fabrication..."/></label><label>Bank details<textarea rows="2" value={form.bankDetails} onChange={e=>set('bankDetails',e.target.value)}/></label><button className="primary" disabled={submitting}>{submitting?'Saving…':'Create vendor'}</button></form>}
